const ids=["G01","G02","G03","G04","G05","G06"];
for(const id of ids){
  const p=await tools.origin_packet({case_id:id}); const c=p.cases[0]; const e=c.evidence;
  const src=new Map();
  for(const m of e.material_index) src.set(m.id,m.source_id);
  // also items/aliases ensure
  for(const it of e.items){ if(!src.has(it.id)&&it.source_id) src.set(it.id,it.source_id); for(const a of it.aliases||[]) if(!src.has(a)&&it.source_id) src.set(a,it.source_id); }
  const parents=new Map();
  for(const l of e.links){ if(l.relation!=="derivation") continue; if(!parents.has(l.child)) parents.set(l.child,[]); parents.get(l.child).push(l.parent); }
  const memo=new Map();
  const visiting=new Set();
  function origins(m){
    if(memo.has(m)) return memo.get(m);
    if(visiting.has(m)) { console.log("CYCLE",id,m); return new Set(); }
    visiting.add(m);
    let out=new Set();
    const ps=parents.get(m)||[];
    if(ps.length===0){ if(src.has(m)) out.add(src.get(m)); else console.log("NOSRC",id,m); }
    else for(const q of ps){ for(const s of origins(q)) out.add(s); }
    visiting.delete(m);
    memo.set(m,out); return out;
  }
  const all=new Set();
  for(const m of src.keys()){ for(const s of origins(m)) all.add(s); }
  // compare precomputed item origins
  let mismatch=0;
  for(const it of e.items){ if(it.origins){ const t=origins(it.id); const a=[...t].sort().join(","); const b=[...it.origins].sort().join(","); if(a!==b){ mismatch++; console.log("MISMATCH",id,it.id,"trav",a,"pre",b);} } }
  console.log(id,"materials",src.size,"computed_origins",all.size,"recorded",e.recorded_origin_count,"mismatchItems",mismatch,"allmatch",JSON.stringify([...all].sort())===JSON.stringify([...e.recorded_origins].sort()));
  for(const q of c.query_ids){ console.log("  ",q,"->",JSON.stringify([...origins(q)].sort())); }
}
